import { Activity, AppWindow, Award, BarChart3, Bell, CalendarDays, Clipboard, Clock3, Copy, Database, Image as ImageIcon, LayoutDashboard, Monitor, MousePointer2, Pause, Play, Search, Settings, ShieldCheck, Square, Timer, Trash2, Keyboard, Power, RefreshCw, Cpu, HardDrive, MemoryStick, Thermometer, Globe2, TrendingUp, TrendingDown, Heart, X, ChevronLeft, ChevronRight, Info } from 'lucide-react';
