function Nav({page,to,set,icon,label}:{page:Page;to:Page;set:(p:Page)=>void;icon:React.ReactNode;label:string}){return <button className={`nav ${page===to?'active':''}`} onClick={()=>set(to)}>{icon}{label}</button>}
function Metric({title,value,foot,icon}:{title:string;value:string;foot:string;icon:React.ReactNode}){return <article className="metric"><div className="metric-head"><span>{title}</span>{icon}</div><b>{value}</b><div className="metric-foot">{foot}</div></article>}
function OverviewPage({data,go}:{data:Overview;go:(p:Page)=>void}){const s=data.system,events=powerHistory(data.power_events),top=data.apps[0];return <>
 <section className="hero"><div className="hero-left"><div className="eyebrow">КОМПЬЮТЕР РАБОТАЕТ</div><div className="hero-value">{longTime(s.uptime_seconds)}</div><p>Windows запущена {date(s.boot_time)} · сейчас активно: <b>{s.active_app}</b></p><div className="progress"><div style={{width:`${Math.min(100,(s.active_seconds/28800)*100)}%`}}/></div><div className="progress-foot"><span>Активное время сегодня: {longTime(s.active_seconds)}</span><span>{data.monitoring_enabled?'Мониторинг':'На паузе'}</span></div></div><div className="hero-focus"><div className="eyebrow">ЧАЩЕ ВСЕГО СЕГОДНЯ</div>{top?<><AppIcon name={top.app_name}/><b>{friendlyApp(top.app_name)}</b><span>{longTime(top.seconds)} активного окна</span><button onClick={()=>go('apps')}>Все приложения <span>→</span></button></>:<><AppWindow size={25}/><b>Собираю статистику</b><span>Топ приложения появятся сегодня</span></>}</div><div className="hero-glow"/></section>
 <section className="metrics"><Metric title="Время в Windows" value={longTime(s.uptime_seconds)} foot={`Загрузка: ${date(s.boot_time)}`} icon={<Power size={16}/>}/><Metric title="Активное время сегодня" value={longTime(s.active_seconds)} foot={`AFK: ${longTime(s.afk_seconds)}`} icon={<Activity size={16}/>}/><Metric title="Нажатия и клики сегодня" value={`${s.key_presses.toLocaleString('ru-RU')} · ${s.mouse_clicks.toLocaleString('ru-RU')}`} foot="Сохраняются только количества" icon={<MousePointer2 size={16}/>}/></section>
 <section className="lower"><article className="panel"><PanelTitle title="Чем пользовался сегодня" sub="Время по активным окнам" action={()=>go('apps')}/>{data.apps.length?<div className="session-list home-app-list">{data.apps.slice(0,10).map((a,i)=><div className="session-row" key={a.app_name}><AppIcon name={a.app_name}/><div className="session-name"><b>{a.app_name}</b><small>Активное окно</small></div><span className="duration">{longTime(a.seconds)}</span><div className="appbar"><i style={{width:`${Math.max(5,100*a.seconds/Math.max(1,data.apps[0].seconds))}%`}}/></div></div>)}</div>:<Empty text="Сбор статистики идёт. Данные появятся после первых минут активности."/>}</article>
 <article className="panel"><PanelTitle title="Запуск и выключение" sub="Системный журнал Windows" action={()=>go('activity')}/>{events.length?<div className="session-list">{events.slice(0,8).map((e,i)=><div className="session-row" key={`${e.event_id}-${e.happened_at}-${i}`}><div className="session-icon"><Power size={15}/></div><div className="session-name"><b>{e.label}</b><small>Событие Windows · {e.event_id}</small></div><span className="duration">{date(e.happened_at)}</span></div>)}</div>:<Empty text="События появятся после чтения журнала Windows. Для старых событий Windows может потребовать права Event Log Readers."/>}</article></section>
 </>}
function ActivityPage({report}:{report:DailyReport|null}){
 const [period,setPeriod]=useState('week'),[analytics,setAnalytics]=useState<AnalyticsData|null>(null),[loading,setLoading]=useState(false),[year,setYear]=useState(new Date().getFullYear()),[calendar,setCalendar]=useState<{year:number;days:{day:string;active_seconds:number;afk_seconds:number;key_presses:number;mouse_clicks:number}[]}|null>(null),[selected,setSelected]=useState<string|null>(null),[showReport,setShowReport]=useState(false);
 useEffect(()=>{let live=true;setLoading(true);invoke<AnalyticsData>('analytics_data',{period}).then(v=>{if(live)setAnalytics(v)}).catch(()=>{if(live)setAnalytics(null)}).finally(()=>{if(live)setLoading(false)});return()=>{live=false}},[period]);
 useEffect(()=>{let live=true;invoke<typeof calendar>('activity_calendar',{year}).then(v=>{if(live)setCalendar(v)}).catch(()=>{if(live)setCalendar(null)});return()=>{live=false}},[year]);
 const points=analytics?.points??[],peak=points.reduce<MetricPoint|null>((best,p)=>!best||p.active_seconds>best.active_seconds?p:best,null),unit=period==='day'?'час':period==='year'||period==='all'?'месяц':'день';
 const records=[{label:'Активное время',field:'active_seconds' as const,icon:<Clock3 size={16}/>},{label:'Нажатия клавиш',field:'key_presses' as const,icon:<Keyboard size={16}/>},{label:'Клики мыши',field:'mouse_clicks' as const,icon:<MousePointer2 size={16}/>}];
 const sums=points.reduce((a,p)=>({active:a.active+p.active_seconds,afk:a.afk+p.afk_seconds,keys:a.keys+p.key_presses,clicks:a.clicks+p.mouse_clicks}),{active:0,afk:0,keys:0,clicks:0});
 const dataByDate=new Map((calendar?.days??[]).map(d=>[d.day,d]));
  const first=new Date(year,0,1,12),count=(new Date(year+1,0,1).getTime()-first.getTime())/86400000,offset=(first.getDay()+6)%7;
  const cells=[...Array(offset).fill(null),...Array.from({length:count},(_,i)=>{const d=new Date(year,0,i+1,12),key=`${year}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`,stats=dataByDate.get(key);return {day:key,active_seconds:stats?.active_seconds??0,afk_seconds:stats?.afk_seconds??0,key_presses:stats?.key_presses??0,mouse_clicks:stats?.mouse_clicks??0}})];
 const activeDays=(calendar?.days??[]).filter(d=>d.active_seconds>0),total=activeDays.reduce((n,d)=>n+d.active_seconds,0),bestDay=activeDays.reduce<typeof activeDays[number]|null>((b,d)=>!b||d.active_seconds>b.active_seconds?d:b,null),average=activeDays.length?Math.round(total/activeDays.length):0;
 const level=(s:number)=>s===0?0:s<7200?1:s<14400?2:s<21600?3:s<28800?4:s<36000?5:s<43200?6:7;
 const periods=[['day','Сегодня'],['week','7 дней'],['month','Этот месяц'],['30d','30 дней'],['year','Этот год'],['all','Всё время']];
 const selectedDay=selected?dataByDate.get(selected):null;
 return <>
  {report&&<article className="panel report-preview"><div><div className="eyebrow">ПОСЛЕДНИЙ ЕЖЕДНЕВНЫЙ ОТЧЁТ</div><h2>{new Date(`${report.day}T12:00:00`).toLocaleDateString('ru-RU',{day:'numeric',month:'long'})}</h2><span>{longTime(report.active_seconds)} активности · {report.mouse_clicks.toLocaleString('ru-RU')} кликов · {report.key_presses.toLocaleString('ru-RU')} нажатий</span></div><button className="secondary-btn" onClick={()=>setShowReport(true)}>Подробный отчёт</button></article>}
  <section className="metrics activity-metrics"><Metric title="Активное время" value={longTime(sums.active)} foot="За выбранный период" icon={<Activity size={16}/>}/><Metric title="Время бездействия" value={longTime(sums.afk)} foot="После 5 минут без ввода" icon={<Clock3 size={16}/>}/><Metric title="Клавиши · клики" value={`${sums.keys.toLocaleString('ru-RU')} · ${sums.clicks.toLocaleString('ru-RU')}`} foot="Считается количество, не текст" icon={<Keyboard size={16}/>}/><Metric title="Пик активности" value={peak?.label??'—'} foot={peak?longTime(peak.active_seconds):'Данные появятся со временем'} icon={<BarChart3 size={16}/>}/></section>
  <article className="panel activity-calendar-panel"><div className="panel-title"><div><h2>Год активности</h2><span>Каждая ячейка — один день · нажми, чтобы увидеть подробности</span></div><div className="year-switch"><button disabled={year<=2000} onClick={()=>{setYear(y=>y-1);setSelected(null)}} aria-label="Предыдущий год"><ChevronLeft size={17}/></button><b>{year}</b><button disabled={year>=new Date().getFullYear()} onClick={()=>{setYear(y=>y+1);setSelected(null)}} aria-label="Следующий год"><ChevronRight size={17}/></button></div></div>
   <div className="calendar-summary"><div><small>Всего за год</small><b>{longTime(total)}</b></div><div><small>Дней с активностью</small><b>{activeDays.length}</b></div><div><small>В среднем за активный день</small><b>{longTime(average)}</b></div><div><small>Самый активный день</small><b>{bestDay?new Date(`${bestDay.day}T12:00:00`).toLocaleDateString('ru-RU',{day:'numeric',month:'short'}):'—'}</b></div></div>
   <div className="calendar-viewport"><div className="calendar-months">{Array.from({length:12},(_,m)=><span key={m}>{new Date(year,m,1).toLocaleDateString('ru-RU',{month:'short'})}</span>)}</div><div className="activity-calendar-grid">{cells.map((d,i)=>d?<button key={d.day} className={`calendar-cell level-${level(d.active_seconds)} ${selected===d.day?'selected':''}`} title={`${new Date(`${d.day}T12:00:00`).toLocaleDateString('ru-RU',{day:'numeric',month:'long',year:'numeric'})} · ${longTime(d.active_seconds)}`} onClick={()=>setSelected(d.day)} aria-label={`${d.day}: ${longTime(d.active_seconds)}`}/>:<span key={`blank-${i}`} className="calendar-cell calendar-empty"/>)}</div></div>
   <div className="calendar-foot"><span>{selectedDay?`${new Date(`${selectedDay.day}T12:00:00`).toLocaleDateString('ru-RU',{weekday:'long',day:'numeric',month:'long'})}: ${longTime(selectedDay.active_seconds)} активности · ${longTime(selectedDay.afk_seconds)} бездействия · ${selectedDay.key_presses.toLocaleString('ru-RU')} клавиш · ${selectedDay.mouse_clicks.toLocaleString('ru-RU')} кликов`:'Выбери день для подробной сводки'}</span><div className="calendar-legend"><small>Меньше</small>{Array.from({length:8},(_,i)=><i key={i} className={`level-${i}`}/>)}<small>Больше</small></div></div>
  </article>
  <section className="records-grid">{records.map(r=><RecordCard key={r.field} label={r.label} icon={r.icon} unit={unit} high={bestPoint(points,r.field)} low={bestPoint(points,r.field,true)} field={r.field}/>)}</section>
  <article className="panel full-panel chart-panel"><div className="panel-title"><div><h2>Активность по времени</h2><span>{loading?'Обновляю…':'Реальные агрегаты из локальной базы'}</span></div><div className="range-tabs">{periods.map(([id,name])=><button className={period===id?'selected':''} key={id} onClick={()=>setPeriod(id)}>{name}</button>)}</div></div><div className="chart-wrap">{points.length?<ResponsiveContainer width="100%" height={250}><AreaChart data={points} margin={{top:12,right:10,left:0,bottom:0}}><defs><linearGradient id="activeFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#a78bfa" stopOpacity={0.3}/><stop offset="95%" stopColor="#8055d8" stopOpacity={0.02}/></linearGradient></defs><CartesianGrid stroke="#24232d" vertical={false}/><XAxis dataKey="label" tick={{fill:'#777783',fontSize:10}} tickLine={false} axisLine={false} minTickGap={18}/><YAxis tickFormatter={v=>`${Math.round(v/60)}м`} tick={{fill:'#777783',fontSize:10}} tickLine={false} axisLine={false} width={38}/><Tooltip contentStyle={{background:'#15151d',border:'1px solid #33313e',borderRadius:8,color:'#f5f5f7',fontSize:11}} formatter={(v:number)=>[longTime(v),'Время']} labelStyle={{color:'#b5a5d5'}}/><Area type="monotone" dataKey="active_seconds" name="Активность" stroke="#a78bfa" strokeWidth={2} fill="url(#activeFill)"/><Area type="monotone" dataKey="afk_seconds" name="Бездействие" stroke="#69527f" strokeWidth={1.5} fill="transparent"/></AreaChart></ResponsiveContainer>:<Empty text="График появится по мере накопления локальной статистики."/>}</div></article>
  {showReport&&report&&<DailyReportDialog report={report} close={()=>setShowReport(false)}/>} 
 </>
}function RecordCard({label,icon,unit,high,low,field}:{label:string;icon:React.ReactNode;unit:string;high:MetricPoint|null;low:MetricPoint|null;field:'active_seconds'|'key_presses'|'mouse_clicks'}){const value=(p:MetricPoint|null)=>!p?'—':field==='active_seconds'?longTime(p[field]):p[field].toLocaleString('ru-RU');return <article className="panel record-card"><div className="record-heading">{icon}<span>{label}</span></div><div className="record-entry high"><TrendingUp size={15}/><div><small>МАКСИМУМ ЗА {unit.toUpperCase()}</small><b>{value(high)}</b><span>{high?.label??'Недостаточно данных'}</span></div></div><div className="record-entry low"><TrendingDown size={15}/><div><small>МИНИМУМ ЗА {unit.toUpperCase()}</small><b>{value(low)}</b><span>{low?.label??'Недостаточно данных'}</span></div></div></article>}
function AppsList({apps,caption}:{apps:AppUse[];caption:string}){return <article className="panel"><PanelTitle title="Используемые приложения" sub={caption}/><div className="session-list">{apps.map((a,i)=><div className="session-row" key={a.app_name}><AppIcon name={a.app_name}/><div className="session-name"><b>{friendlyApp(a.app_name)}</b><small>{i===0?'Самое активное':'Время активного окна'}</small></div><span className="duration">{longTime(a.seconds)}</span><div className="appbar"><i style={{width:`${Math.max(4,100*a.seconds/Math.max(1,apps[0]?.seconds||1))}%`}}/></div></div>)}</div>{!apps.length&&<Empty text="Пока нет данных. Оставь мониторинг включённым."/>}</article>}
function AppsPage(){
 const [period,setPeriod]=useState('day');
 const [apps,setApps]=useState<AppUse[]>([]);
 const [query,setQuery]=useState('');
 const [sort,setSort]=useState<'time'|'name'>('time');
 const [loading,setLoading]=useState(false);
 useEffect(()=>{let live=true;setLoading(true);invoke<AnalyticsData>('analytics_data',{period}).then(v=>{if(live)setApps(v.apps)}).catch(()=>{if(live)setApps([])}).finally(()=>{if(live)setLoading(false)});return()=>{live=false}},[period]);
 const total=apps.reduce((n,a)=>n+a.seconds,0);
 const filtered=apps.filter(a=>friendlyApp(a.app_name).toLowerCase().includes(query.toLowerCase())).sort(sort==='time'?(a,b)=>b.seconds-a.seconds:(a,b)=>friendlyApp(a.app_name).localeCompare(friendlyApp(b.app_name),'ru'));
 const periods=[['day','Сегодня'],['week','7 дней'],['month','Месяц'],['30d','30 дней'],['all','Всё время']];
 return <div className="apps-dashboard">
  <section className="apps-intro"><div><div className="eyebrow">КАК РАСПРЕДЕЛЯЕТСЯ МОЁ ВРЕМЯ</div><h2>Приложения</h2><p>Время считается, когда окно приложения активно на экране. Названия документов и страниц не сохраняются.</p></div><div className="range-tabs">{periods.map(([id,label])=><button key={id} className={period===id?'selected':''} onClick={()=>setPeriod(id)}>{label}</button>)}</div></section>
  <section className="apps-summary"><article className="apps-total"><small>АКТИВНОЕ ВРЕМЯ</small><b>{longTime(total)}</b><span>За выбранный период</span></article><article><AppWindow size={17}/><small>ПРИЛОЖЕНИЯ</small><b>{apps.length}</b><span>С видимой активностью</span></article><article className="apps-top-card">{apps[0]&&<AppIcon name={apps[0].app_name}/>}<small>ЛИДЕР ПО ВРЕМЕНИ</small><b>{apps[0]?friendlyApp(apps[0].app_name):'—'}</b><span>{apps[0]?longTime(apps[0].seconds):'Пока нет данных'}</span></article><article><BarChart3 size={17}/><small>СРЕДНЕЕ НА ПРИЛОЖЕНИЕ</small><b>{apps.length?longTime(Math.round(total/apps.length)):'—'}</b><span>Только активное окно</span></article></section>
  <article className="panel full-panel apps-full-list"><div className="panel-title"><div><h2>Всё использование</h2><span>{loading?'Обновляю данные…':`Доли от ${longTime(total)} суммарно`}</span></div><div className="apps-controls"><label className="clip-search"><Search size={15}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Найти приложение"/></label><select value={sort} onChange={e=>setSort(e.target.value as 'time'|'name')}><option value="time">По времени</option><option value="name">По названию</option></select></div></div>
   {filtered.length>0?<div className="apps-ranking">{filtered.map((app,i)=>{const share=total?100*app.seconds/total:0;return <div className="app-rank-row" key={app.app_name}><span className="app-rank-index">{String(i+1).padStart(2,'0')}</span><AppIcon name={app.app_name}/><div className="app-rank-main"><div className="app-rank-title"><b>{friendlyApp(app.app_name)}</b><span>{longTime(app.seconds)} · {share.toFixed(1)}%</span></div><div className="app-rank-track"><i style={{width:`${Math.max(1,share)}%`}}/></div></div></div>})}</div>:<Empty text={query?'Не нашёл такое приложение.':'Пока нет статистики за этот период. Оставь мониторинг включённым.'}/>}
  </article>
  <div className="apps-footnote"><ShieldCheck size={15}/>Отслеживается только имя активного приложения и длительность. Содержимое окон не записывается.</div>
 </div>
}function friendlyApp(name:string){const n=name.toLowerCase();if(n.includes('chatgpt'))return 'ChatGPT';if(n.includes('discord'))return 'Discord';if(n.includes('firefox'))return 'Firefox';if(n.includes('chrome'))return 'Google Chrome';if(n.includes('msedge')||n.includes('edge'))return 'Microsoft Edge';if(n.includes('telegram'))return 'Telegram';if(n.includes('ayugram'))return 'AyuGram';if(n.includes('steam'))return 'Steam';return name.replace(/\.exe$/i,'').replace(/([a-z])([A-Z])/g,'$1 $2')}
function AppIcon({name}:{name:string}){const n=name.toLowerCase();const kind=n.includes('chatgpt')?'gpt':n.includes('discord')?'discord':n.includes('firefox')?'firefox':n.includes('chrome')?'chrome':(n.includes('telegram')||n.includes('ayugram'))?'telegram':n.includes('steam')?'steam':'generic';const letters=friendlyApp(name).split(/\s+/).map(x=>x[0]).slice(0,2).join('').toUpperCase();return <div className={`app-logo ${kind}`} title={friendlyApp(name)}>{kind==='gpt'?<svg viewBox="0 0 32 32" aria-hidden="true"><path d="M16 4.2c4.5-2.6 9.8.7 9.8 5.7v1.4a5.7 5.7 0 0 1 2.9 9.9l-1.2.8a5.7 5.7 0 0 1-6.8 7.8l-1.3-.6a5.7 5.7 0 0 1-10.8-1.8l-.1-1.4a5.7 5.7 0 0 1-6-8.2l.8-1.2a5.7 5.7 0 0 1 3.3-9.8l1.4-.1A5.7 5.7 0 0 1 16 4.2Z" fill="none" stroke="currentColor" strokeWidth="1.8"/><path d="m11 10 10 5.8v7.1M21 10l-10 5.8v7.1M7.7 13l6.8-3.9M24.3 13l-6.8-3.9M8.2 22.5l6.8-3.9M23.8 22.5 17 18.6" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round"/></svg>:kind==='discord'?<svg viewBox="0 0 32 32" aria-hidden="true"><path d="M24.7 8.4a21 21 0 0 0-5.2-1.6l-.7 1.5a19 19 0 0 0-5.6 0l-.7-1.5a21 21 0 0 0-5.2 1.6C4 13.2 3.1 18 3.5 22.8a21 21 0 0 0 6.4 3.2l1.4-2.3-2.2-1.1.5-.4c4.2 2 8.7 2 12.8 0l.5.4-2.2 1.1 1.4 2.3a21 21 0 0 0 6.4-3.2c.5-5.6-.8-10.3-3.8-14.4ZM12 19.3c-1.2 0-2.1-1.1-2.1-2.4s.9-2.4 2.1-2.4 2.1 1.1 2.1 2.4-.9 2.4-2.1 2.4Zm8 0c-1.2 0-2.1-1.1-2.1-2.4s.9-2.4 2.1-2.4 2.1 1.1 2.1 2.4-.9 2.4-2.1 2.4Z" fill="currentColor"/></svg> :kind==='firefox'?<svg viewBox="0 0 32 32" aria-hidden="true"><defs><linearGradient id="ff" x1="0" y1="1" x2="1" y2="0"><stop stopColor="#ff9f0a"/><stop offset=".55" stopColor="#ff4b24"/><stop offset="1" stopColor="#a125e8"/></linearGradient></defs><circle cx="16" cy="16" r="13" fill="url(#ff)"/><circle cx="16" cy="16" r="6.5" fill="#4422a8"/><path d="M6 7c4 1 6 3 7 6-3-2-5-2-8-1 2 2 4 3 7 3-2 3-5 4-8 3 1 6 8 9 14 6 7-3 8-12 3-17 1 5-1 7-4 8 2-4 0-9-4-12 1 4 0 6-3 7C9 7 8 5 6 7Z" fill="#ffb11b"/></svg>:kind==='chrome'?<svg viewBox="0 0 32 32" aria-hidden="true"><circle cx="16" cy="16" r="14" fill="#e94435"/><path d="M16 16 8.8 28.1A14 14 0 0 1 3.9 8.8h14.2Z" fill="#34a853"/><path d="M18.1 8.8H3.9a14 14 0 0 1 24.2-2.1l-7.2 12.4Z" fill="#fbbc05"/><circle cx="16" cy="16" r="6.5" fill="#4285f4" stroke="#e8f0fe" strokeWidth="1.5"/></svg>:kind==='telegram'?<svg viewBox="0 0 32 32" aria-hidden="true"><circle cx="16" cy="16" r="14" fill="#229ed9"/><path d="m7 15 17-6-4 16-5-5-3 3 .4-5.2 9-6.5-11 5.4Z" fill="white"/></svg>:kind==='steam'?<svg viewBox="0 0 32 32" aria-hidden="true"><circle cx="21" cy="10" r="7" fill="none" stroke="currentColor" strokeWidth="3"/><circle cx="21" cy="10" r="2" fill="currentColor"/><circle cx="10" cy="21" r="6" fill="none" stroke="currentColor" strokeWidth="3"/><path d="m14 18 5-5M5 19l8 3" stroke="currentColor" strokeWidth="3" strokeLinecap="round"/></svg>:<span>{letters||'?'}</span>}</div>}
function HardwarePage(){const [info,setInfo]=useState<HardwareInfo|null>(null),[loading,setLoading]=useState(false),[error,setError]=useState('');const load=useCallback(async()=>{setLoading(true);try{setInfo(await invoke<HardwareInfo>('hardware_snapshot'));setError('')}catch(e){setError(String(e))}finally{setLoading(false)}},[]);useEffect(()=>{load()},[load]);if(loading&&!info)return <div className="panel loading"><Cpu size={24}/><p>Читаю сведения Windows и датчики…</p></div>;if(error)return <article className="panel full-panel"><div className="error">Не удалось получить характеристики: {error}</div><button className="primary retry-btn" onClick={load}>Повторить запрос</button></article>;if(!info)return null;const ramPct=info.memoryTotalBytes?100*info.memoryUsedBytes/info.memoryTotalBytes:0;return <><section className="hardware-banner"><div className="hardware-orb"><Cpu size={32}/></div><div><div className="eyebrow">МОЯ СИСТЕМА</div><h2>{info.computerModel}</h2><p>{info.osName} · {info.osVersion}</p></div><button className="refresh-btn" title="Обновить характеристики" onClick={load} disabled={loading}><RefreshCw size={15}/></button></section><section className="sensor-grid"><article className="sensor-card cpu-temp"><div className="sensor-icon"><Thermometer size={19}/></div><div><small>ТЕМПЕРАТУРА ПРОЦЕССОРА</small><b>{info.cpuTempC==null?'Датчик недоступен':`${info.cpuTempC.toFixed(0)}°C`}</b><span>{info.cpuTempC==null?'Прямой датчик CPU недоступен':info.sensorProvider??'Системный датчик'}</span></div></article>{info.gpu.map((g,i)=><article className="sensor-card gpu-temp" key={`${g.name}-${i}`}><div className="sensor-icon"><Thermometer size={19}/></div><div><small>ТЕМПЕРАТУРА ВИДЕОКАРТЫ {info.gpu.length>1?i+1:''}</small><b>{g.temperatureC==null?'Датчик недоступен':`${g.temperatureC.toFixed(0)}°C`}</b><span>{g.loadPercent==null?'Нагрузка недоступна':`Нагрузка ${g.loadPercent.toFixed(0)}%`}</span></div></article>)}</section><section className="spec-grid"><article className="panel spec-card"><div className="spec-icon cpu"><Cpu size={18}/></div><div className="eyebrow">ПРОЦЕССОР</div><h3>{info.processor||'Не определён'}</h3><div className="spec-pills"><span>{info.cpuCores} ядра</span><span>{info.cpuThreads} потока</span><span>до {(info.cpuClockMhz/1000).toFixed(1)} ГГц</span></div></article>{info.gpu.map((g,i)=><article className="panel spec-card" key={`gpu-${i}`}><div className="spec-icon gpu"><Monitor size={18}/></div><div className="eyebrow">ВИДЕОКАРТА {info.gpu.length>1?i+1:''}</div><h3>{g.name}</h3><div className="spec-pills"><span>{g.memoryBytes?formatBytes(g.memoryBytes)+' VRAM':'Объём VRAM не сообщён'}</span><span>Драйвер {g.driverVersion||'—'}</span></div></article>)}<article className="panel spec-card"><div className="spec-icon ram"><MemoryStick size={18}/></div><div className="eyebrow">ОПЕРАТИВНАЯ ПАМЯТЬ</div><h3>{formatBytes(info.memoryTotalBytes)}</h3><div className="spec-progress"><i style={{width:`${Math.min(100,ramPct)}%`}}/></div><div className="spec-caption">Занято {formatBytes(info.memoryUsedBytes)} · свободно {formatBytes(Math.max(0,info.memoryTotalBytes-info.memoryUsedBytes))}</div></article><article className="panel spec-card"><div className="spec-icon disk"><HardDrive size={18}/></div><div className="eyebrow">НАКОПИТЕЛИ</div>{info.drives.map(d=>{const used=d.totalBytes-d.freeBytes,pct=d.totalBytes?100*used/d.totalBytes:0;return <div className="drive-stat" key={d.name}><div><b>{d.name}</b><span>{formatBytes(d.freeBytes)} свободно / {formatBytes(d.totalBytes)}</span></div><div className="spec-progress"><i style={{width:`${Math.min(100,pct)}%`}}/></div></div>})}</article><article className="panel spec-card"><div className="spec-icon board"><Monitor size={18}/></div><div className="eyebrow">ПЛАТА И СИСТЕМА</div><h3>{info.motherboard}</h3><div className="spec-caption">{info.osName} · версия {info.osVersion}</div></article></section><div className="sensor-note"><Thermometer size={16}/><span>LifeOS показывает только температуры, которые реально сообщает драйвер или LibreHardwareMonitor. Если датчик недоступен, программа не подставляет приблизительные значения.</span><button className="text-btn" onClick={load}>{loading?'Обновляю…':'Обновить данные'}</button></div></>}
function BrowserPage({data,toggle,clear,busy}:{data:Overview;toggle:(v:boolean)=>void;clear:()=>void;busy:boolean}){const pages=data.firefox_pages,total=pages.reduce((n,p)=>n+p.active_seconds,0);return <><section className="browser-banner"><div className="browser-symbol"><Globe2 size={24}/></div><div><div className="eyebrow">ЛОКАЛЬНОЕ НАБЛЮДЕНИЕ</div><h2>Активные вкладки браузеров</h2><p>Сохраняются заголовки вкладок и время, пока Firefox или Chrome открыт на экране.</p></div><div className="browser-toggle"><span>{data.firefox_tracking_enabled?'Запись включена':'Запись выключена'}</span><button className={`switch ${data.firefox_tracking_enabled?'on':''}`} aria-pressed={data.firefox_tracking_enabled} disabled={busy} onClick={()=>toggle(!data.firefox_tracking_enabled)}><i/></button></div></section><section className="metrics browser-metrics"><Metric title="Разных заголовков" value={pages.length.toLocaleString('ru-RU')} foot="За последние 180 дней" icon={<Globe2 size={16}/>}/><Metric title="Время в браузерах" value={longTime(total)} foot="Firefox и Chrome" icon={<Clock3 size={16}/>}/><Metric title="Последняя вкладка" value={pages[0]?.title??'Пока нет данных'} foot={pages[0]?date(pages[0].last_seen):'Открой Firefox при включённом мониторинге'} icon={<Activity size={16}/>}/></section><article className="panel full-panel browser-history"><div className="panel-title"><div><h2>Недавно открытые вкладки</h2><span>Последние 100 · история старше 180 дней очищается автоматически</span></div>{pages.length>0&&<button className="danger-outline" onClick={()=>{if(window.confirm('Удалить локальную историю браузеров?'))clear()}}>Удалить историю</button>}</div>{pages.length?<div className="browser-list">{pages.map((p,i)=><div className="browser-row" key={`${p.title}-${i}`}><div className="browser-rank">{String(i+1).padStart(2,'0')}</div><Globe2 className="browser-row-icon" size={17}/><div className="session-name"><b title={p.title}>{p.title}</b><small>Активна {longTime(p.active_seconds)} · последняя активность {date(p.last_seen)}</small></div><span className="duration">{longTime(p.active_seconds)}</span></div>)}</div>:<Empty text="Пока нет записей. При включённой записи LifeOS запомнит заголовок активной вкладки Firefox и Chrome и их время."/>}</article><div className="privacy-detail"><ShieldCheck size={18}/><p>Сохраняется только заголовок видимой вкладки и счётчик времени в локальной базе. URL, содержимое страниц, формы и ввод не читаются. Окна приватного просмотра Firefox и инкогнито Chrome пропускаются. Отключить сбор или очистить историю можно здесь.</p></div></>}
function DevicesPage({data}:{data:Overview}){return <><section className="metrics"><Metric title="Клавиши" value={data.system.key_presses.toLocaleString('ru-RU')} foot="Счётчик нажатий · без сохранения текста" icon={<Keyboard size={16}/>}/><Metric title="Клики мыши" value={data.system.mouse_clicks.toLocaleString('ru-RU')} foot="Левая, правая и средняя кнопки" icon={<MousePointer2 size={16}/>}/><Metric title="Активное приложение" value={friendlyApp(data.system.active_app)} foot="Сейчас на переднем плане" icon={<AppWindow size={16}/>}/></section><article className="panel full-panel"><PanelTitle title="Приватность ввода" sub="LifeOS считает количество событий, но не записывает содержимое клавиш"/><div className="privacy-detail"><ShieldCheck size={20}/><p>Нажатия считаются локально в памяти и записываются в SQLite пакетами раз в 15 секунд. Пароли, тексты и комбинации клавиш не сохраняются. Наблюдение можно приостановить в настройках.</p></div></article></>}
function ClipboardPage({data,copy,copyImage,remove,clear}:{data:Overview;copy:(t:string)=>void;copyImage:(id:number)=>void;remove:(id:number)=>void;clear:()=>void}){
 const [search,setSearch]=useState(''),[opened,setOpened]=useState<ClipItem|null>(null);
 const items=data.clipboard.filter(item=>`${item.content} ${item.kind}`.toLowerCase().includes(search.toLowerCase()));
 return <><article className="panel full-panel clipboard-page"><div className="panel-title"><div><h2>Сохранённые элементы</h2><span>{data.clipboard.length} последних · лимит хранилища {data.clipboard_max_mb} МБ</span></div>{data.clipboard.length>0&&<button className="danger-outline" onClick={()=>{if(window.confirm('Удалить всю историю буфера и сохранённые изображения?'))clear()}}><Trash2 size={14}/>Очистить всё</button>}</div>
 <div className="clip-toolbar"><label className="clip-search"><Search size={16}/><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Найти текст или изображение"/><span>{items.length}</span></label></div>
 {!data.clipboard_enabled&&<div className="notice"><ShieldCheck size={16}/>История буфера выключена. Включи её в настройках, чтобы сохранять скопированное.</div>}
 {data.clipboard_enabled&&!data.clipboard_images_enabled&&<div className="notice"><ImageIcon size={16}/>Сохранение изображений выключено и не включится без твоего разрешения. Его можно включить в настройках.</div>}
 <div className="clip-list">{items.map(c=><div className={`clip-item ${c.kind==='image'?'clip-image-item':''}`} key={c.id}>{c.kind==='image'&&c.image_data?<button className="clip-image-preview" onClick={()=>setOpened(c)} aria-label="Открыть изображение"><img src={c.image_data} alt="Скопированное изображение"/></button>:<div className="clip-text">{c.content}</div>}<div className="clip-meta"><span>{c.kind==='image'?'Изображение · ':''}{date(c.copied_at)}</span><div>{c.kind==='image'?<button className="icon-btn" title="Вернуть изображение в буфер обмена" onClick={()=>copyImage(c.id)}><Copy size={15}/></button>:<button className="icon-btn" title="Вернуть текст в буфер обмена" onClick={()=>copy(c.content)}><Copy size={15}/></button>}<button className="icon-btn" title="Удалить запись" onClick={()=>{if(window.confirm('Удалить эту запись?'))remove(c.id)}}><Trash2 size={15}/></button></div></div></div>)}</div>
 {!items.length&&<Empty text={search?'Ничего не найдено.':'Сохранённых элементов пока нет.'}/>}</article>
 {opened&&<div className="image-lightbox" role="dialog" aria-modal="true" onClick={()=>setOpened(null)}><button className="lightbox-close" onClick={()=>setOpened(null)} aria-label="Закрыть"><X size={20}/></button><img src={opened.image_data??''} alt="Скопированное изображение в полном размере" onClick={e=>e.stopPropagation()}/></div>}</>
}function AchievementGlyph({icon}:{icon:string}){const icons:Record<string,React.ReactNode>={MousePointer2:<MousePointer2 size={19}/>,Clock3:<Clock3 size={19}/>,Activity:<Activity size={19}/>,AppWindow:<AppWindow size={19}/>,CalendarDays:<CalendarDays size={19}/>,Eye:<Activity size={19}/>,Globe2:<Globe2 size={19}/>,Image:<ImageIcon size={19}/>};return <span className="achievement-glyph">{icons[icon]??<Award size={19}/>}</span>}
function AchievementsPage(){
 const [items,setItems]=useState<AchievementItem[]>([]),[filter,setFilter]=useState<'all'|'earned'|'locked'>('all'),[loading,setLoading]=useState(true);
 const load=useCallback(async()=>{try{setItems(await invoke<AchievementItem[]>('achievements_data'))}finally{setLoading(false)}},[]);
 useEffect(()=>{load();const timer=setInterval(load,15000);return()=>clearInterval(timer)},[load]);
 const earned=items.filter(a=>a.unlocked_at),shown=items.filter(a=>filter==='all'||(filter==='earned'?!!a.unlocked_at:!a.unlocked_at)),rarityName:Record<string,string>={Common:'Обычное',Uncommon:'Необычное',Rare:'Редкое',Epic:'Эпическое',Legendary:'Легендарное'};
 return <div className="achievement-page"><section className="achievement-overview"><div><div className="eyebrow">ЛИЧНЫЕ РЕЗУЛЬТАТЫ</div><h2>Каждый шаг имеет значение</h2><p>Достижения открываются автоматически по реальным данным LifeOS. Ничего не начисляется задним числом на основе выдуманной статистики.</p></div><div className="achievement-score"><Award size={21}/><b>{earned.length}<small> / {items.length}</small></b><span>получено</span></div></section><div className="achievement-filters">{([['all','Все'],['earned','Получены'],['locked','Впереди']] as const).map(([id,label])=><button key={id} className={filter===id?'selected':''} onClick={()=>setFilter(id)}>{label}{id==='earned'?` · ${earned.length}`:''}</button>)}</div>{loading&&!items.length?<div className="panel loading">Считаю достижения по твоей статистике…</div>:<div className="achievement-grid">{shown.map(a=>{const done=!!a.unlocked_at,pct=a.target?Math.min(100,100*a.progress/a.target):0;return <article key={a.id} className={`panel achievement-card ${done?'earned':''} rarity-${a.rarity.toLowerCase()}`}><div className="achievement-card-top"><AchievementGlyph icon={a.icon}/><span className={`rarity-tag rarity-${a.rarity.toLowerCase()}`}>{rarityName[a.rarity]??a.rarity}</span></div><h3>{a.title}</h3><p>{a.description}</p><div className="achievement-progress"><i style={{width:`${pct}%`}}/></div><div className="achievement-card-bottom"><span>{done?`Получено ${date(a.unlocked_at!)}`:`${a.progress.toLocaleString('ru-RU')} / ${a.target.toLocaleString('ru-RU')}`}</span><b>{Math.floor(pct)}%</b></div></article>})}{!shown.length&&<div className="panel achievement-empty">Здесь пока пусто. Оставь мониторинг включённым — достижения проверяются автоматически.</div>}</div>}</div>
}
function AchievementToast({item,effects,close}:{item:AchievementItem;effects:boolean;close:()=>void}){return <div className={`achievement-toast ${effects?'celebrate':''}`} role="status">{effects&&<div className="confetti" aria-hidden="true">{Array.from({length:28},(_,i)=><i key={i} style={{'--i':i} as React.CSSProperties}/>)}</div>}<div className="toast-badge"><AchievementGlyph icon={item.icon}/></div><div className="toast-copy"><small>НОВОЕ ДОСТИЖЕНИЕ · {item.rarity.toUpperCase()}</small><b>{item.title}</b><span>{item.description}</span></div><button className="icon-btn" onClick={close} aria-label="Закрыть"><X size={17}/></button></div>}

function AboutDialog({close}:{close:()=>void}){
 const openLink=(url:string)=>{openUrl(url).catch(()=>{window.open(url,'_blank')})};
 return <div className="report-backdrop" role="dialog" aria-modal="true" onClick={close}><article className="panel report-dialog about-dialog" onClick={e=>e.stopPropagation()}>
  <button className="lightbox-close" onClick={close} aria-label="Закрыть"><X size={20}/></button>
  <div className="eyebrow">О ПРОЕКТЕ</div>
  <h2>LifeOS</h2>
  <p>Личный журнал активности компьютера. Все данные хранятся локально.</p>
  <div className="about-section"><b>Разработчики</b><span>Claude · Codex · Gemini · Hikkanilo</span></div>
  <div className="about-section"><b>GitHub</b><button className="text-btn" onClick={()=>openLink('https://github.com/hikkanilo/LifeOS')}>github.com/hikkanilo/LifeOS</button></div>
  <div className="about-actions">
   <button className="support-button" onClick={()=>openLink('https://boosty.to/montonmef')}><Heart size={15} fill="currentColor"/>Поддержать на Boosty</button>
   <button className="primary" onClick={close}>Закрыть</button>
  </div>
 </article></div>
}
function DailyReportDialog({report,close}:{report:DailyReport;close:()=>void}){const day=new Date(`${report.day}T12:00:00`).toLocaleDateString('ru-RU',{weekday:'long',day:'numeric',month:'long'});return <div className="report-backdrop" role="dialog" aria-modal="true" onClick={close}><article className="panel report-dialog" onClick={e=>e.stopPropagation()}><button className="lightbox-close" onClick={close} aria-label="Закрыть"><X size={20}/></button><div className="eyebrow">ТВОЙ ДЕНЬ В LIFEOS</div><h2>Сводка за {day}</h2><p>Все числа собраны локально. Нажатые клавиши и тексты буфера не раскрываются в отчёте.</p><div className="report-stats"><div><small>Активное время</small><b>{longTime(report.active_seconds)}</b></div><div><small>Без движения</small><b>{longTime(report.afk_seconds)}</b></div><div><small>Клики мышью</small><b>{report.mouse_clicks.toLocaleString('ru-RU')}</b></div><div><small>Нажатия клавиш</small><b>{report.key_presses.toLocaleString('ru-RU')}</b></div><div><small>Переключения окон</small><b>{report.window_switches.toLocaleString('ru-RU')}</b></div><div><small>Приложения с активностью</small><b>{report.app_count}</b></div></div><div className="report-highlight"><AppWindow size={18}/><span>Чаще всего было открыто</span><b>{report.top_app?friendlyApp(report.top_app):'Нет данных'}</b></div>{report.achievement_count>0&&<div className="report-highlight"><Award size={18}/><span>Новые достижения</span><b>{report.achievement_count}</b></div>}{report.new_records.length>0&&<div className="report-records"><b>Новые личные рекорды</b>{report.new_records.map(r=><span key={r}>{r}</span>)}</div>}<button className="primary" onClick={close}>Продолжить</button></article></div>}function SettingsPage({data,monitoring,clipboard,clipboardImages,clipboardLimit,clipboardExclusions,dailyReport,achievementNotifications,effects,autostart,busy}:{data:Overview;monitoring:(v:boolean)=>void;clipboard:(v:boolean)=>void;clipboardImages:(v:boolean)=>void;clipboardLimit:(v:number)=>void;clipboardExclusions:(v:string)=>void;dailyReport:(enabled:boolean,time:string)=>void;achievementNotifications:(v:boolean)=>void;effects:(v:boolean)=>void;autostart:(v:boolean)=>void;busy:boolean}){
 const [excluded,setExcluded]=useState(data.clipboard_excluded_apps),[saved,setSaved]=useState(false),[reportTime,setReportTime]=useState(data.daily_report_time);
 useEffect(()=>setExcluded(data.clipboard_excluded_apps),[data.clipboard_excluded_apps]);useEffect(()=>setReportTime(data.daily_report_time),[data.daily_report_time]);
 const saveExcluded=()=>{clipboardExclusions(excluded);setSaved(true);window.setTimeout(()=>setSaved(false),1800)}; const openSupport=()=>{void openUrl("https://boosty.to/montonmef")};
 return <article className="panel full-panel settings-page"><PanelTitle title="Настройки LifeOS" sub="Все параметры и данные остаются на этом компьютере"/><Setting title="Мониторинг активности" text="Считает активное время, бездействие и количество событий ввода. Текст клавиш не записывается." checked={data.monitoring_enabled} disabled={busy} change={monitoring}/><Setting title="История текста буфера" text="Сохраняет скопированный текст локально. Выключено по умолчанию." checked={data.clipboard_enabled} disabled={busy} change={clipboard}/><Setting title="Сохранение изображений" text="Сохраняет картинки из буфера только после отдельного разрешения. Ограничено заданным объёмом." checked={data.clipboard_images_enabled} disabled={busy||!data.clipboard_enabled} change={clipboardImages}/><div className="clip-setting-row"><div><b>Лимит изображений</b><small>При достижении лимита самые старые файлы удаляются автоматически.</small></div><select value={data.clipboard_max_mb} disabled={busy} onChange={e=>clipboardLimit(Number(e.target.value))}><option value={25}>25 МБ</option><option value={50}>50 МБ</option><option value={100}>100 МБ</option><option value={250}>250 МБ</option><option value={500}>500 МБ</option></select></div><div className="clip-exclusions"><label htmlFor="clip-excluded"><b>Исключить приложения из буфера</b><small>Имена процессов через запятую: KeePass.exe, 1Password.exe.</small></label><div><input id="clip-excluded" value={excluded} onChange={e=>setExcluded(e.target.value)} placeholder="KeePass.exe, 1Password.exe"/><button className="secondary-btn" onClick={saveExcluded} disabled={busy}>{saved?'Сохранено':'Сохранить'}</button></div></div><div className="report-settings"><div><b>Ежедневный отчёт</b><small>Сводка за предыдущий день придёт один раз в выбранное время.</small></div><div className="report-schedule"><input type="time" value={reportTime} onChange={e=>setReportTime(e.target.value)} disabled={busy||!data.daily_report_enabled}/><button className="secondary-btn" onClick={()=>dailyReport(data.daily_report_enabled,reportTime)} disabled={busy}>Сохранить время</button></div><button className={`switch ${data.daily_report_enabled?'on':''}`} aria-pressed={data.daily_report_enabled} disabled={busy} onClick={()=>dailyReport(!data.daily_report_enabled,reportTime)}><i/></button></div><Setting title="Уведомления о достижениях" text="Windows покажет уведомление, когда условие достижения выполнено." checked={data.achievement_notifications_enabled} disabled={busy} change={achievementNotifications}/><Setting title="Конфетти и анимации" text="Управляет праздничными эффектами. Уважает системную настройку Reduced Motion." checked={data.effects_enabled} disabled={busy} change={effects}/><Setting title="Запуск вместе с Windows" text="LifeOS запускается при входе и продолжает мониторинг в трее." checked={data.autostart_enabled} disabled={busy} change={autostart}/><div className="data-location"><Database size={17}/><div><b>Где хранятся данные</b><span>Папка data рядом с программой</span><small>SQLite, отчёты и локальные изображения; остаются при обновлении</small></div></div><div className="privacy-detail"><ShieldCheck size={20}/><p>Клавиатурные нажатия сохраняются только как количество. Буфер и изображения сохраняются лишь с твоего согласия. Статистика не отправляется в интернет.</p></div><section className="support-card"><div className="support-copy"><span className="support-heart"><Heart size={19} fill="currentColor"/></span><div><b>Поддержать LifeOS</b><small>Сделано разработчиком Hikkanilo &lt;3 · Будем рады поддержке</small></div></div><button className="support-button" onClick={openSupport}><Heart size={15} fill="currentColor"/>Поддержать на Boosty</button></section></article>
}function Setting({title,text,checked,disabled,change}:{title:string;text:string;checked:boolean;disabled:boolean;change:(v:boolean)=>void}){return <div className="setting-row"><div><b>{title}</b><small>{text}</small></div><button className={`switch ${checked?'on':''}`} aria-pressed={checked} disabled={disabled} onClick={()=>change(!checked)}><i/></button></div>}
function PanelTitle({title,sub,action}:{title:string;sub:string;action?:()=>void}){return <div className="panel-title"><div><h2>{title}</h2><span>{sub}</span></div>{action&&<button className="text-btn" onClick={action}>Все данные →</button>}</div>}
function Empty({text}:{text:string}){return <div className="empty"><div className="empty-icon"><Database size={20}/></div><span>{text}</span></div>}
createRoot(document.getElementById('root')!).render(<React.StrictMode><App/></React.StrictMode>);
